fn frame(t: i32) {
    host::display::clear(0x101018);
    if host::display::state_get(0) == 0 {
        let h: i32 = host::http::get("https://example.com/robots.txt", 30);
        host::display::state_set(1, h);
        if h < 0 {
            host::display::state_set(0, 3);
        } else {
            host::display::state_set(0, 1);
        }
    }
    let h2: i32 = host::display::state_get(1);
    if host::display::state_get(0) == 1 {
        let r: i32 = host::http::ready(h2);
        if r == 1 {
            host::display::state_set(0, 2);
        } else if r < 0 {
            host::display::state_set(0, 3);
        }
    }
    let phase: i32 = host::display::state_get(0);
    host::display::draw_string(8, 8, "TEXT VIEWER", 0xffffff, 2);
    host::display::fill_rect(0, 30, 512, 2, 0x333333);
    if phase == 1 {
        host::display::draw_string(8, 60, "FETCHING", 0xaa7700, 1);
        if (t / 20) % 2 == 0 {
            host::display::fill_rect(70, 58, 8, 8, 0xaa7700);
        }
    } else if phase == 2 {
        let total: i32 = host::http::body_lines(h2);
        let mut n: i32 = total;
        if n > 14 {
            n = 14;
        }
        for i in 0..n {
            host::http::draw_line(h2, i, 8, 48 + i * 14, 0xcccccc, 1);
        }
        host::display::draw_string(8, 480, "LINES", 0x888888, 1);
        host::display::draw_number(56, 478, total, 0xffffff, 1);
    } else {
        host::display::draw_string(8, 60, "FETCH FAILED", 0xbb3333, 2);
    }
    host::display::present();
}
